const questionBankRound2 = {};

// Bank TTS berisi total 1.250 soal di 6 kategori.
// Setiap permainan hanya mengambil 25 soal secara acak. Riwayat menyimpan
// soal yang sudah diselesaikan agar permainan berikutnya memakai soal berbeda.
// Setelah seluruh variasi pada suatu kategori selesai, siklus baru dimulai.
let currentRound=1;
let activeQuestionSet=[];
const QUESTION_COUNT_PER_ROUND=25;
const QUESTION_HISTORY_KEY="pplg2_tts_completed_questions_v2";

function questionKey(q){ return `${q[0]}\u0000${q[1]}`; }
function loadQuestionHistory(){
  try { return JSON.parse(localStorage.getItem(QUESTION_HISTORY_KEY)||"{}"); }
  catch(e){ return {}; }
}
function saveQuestionHistory(history){
  try { localStorage.setItem(QUESTION_HISTORY_KEY, JSON.stringify(history)); }
  catch(e){}
}
function shuffleQuestions(arr){
  const copy=[...arr];
  for(let i=copy.length-1;i>0;i--){
    const j=Math.floor(Math.random()*(i+1));
    [copy[i],copy[j]]=[copy[j],copy[i]];
  }
  return copy;
}
function getQuestionPool(category){
  const pool=questionBank[category]||[];
  const seen=new Set();
  return pool.filter(q=>{
    const key=questionKey(q);
    if(seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}
function selectUniqueAnswerQuestions(pool,count,used){
  // Pilih maksimal satu variasi untuk setiap jawaban dalam satu putaran,
  // supaya papan TTS tidak dipenuhi kata jawaban yang sama.
  const byAnswer=new Map();
  pool.filter(q=>!used.has(questionKey(q))).forEach(q=>{
    const answer=cleanWord(q[1]);
    if(!byAnswer.has(answer)) byAnswer.set(answer,[]);
    byAnswer.get(answer).push(q);
  });
  const groups=shuffleQuestions([...byAnswer.values()]);
  const selected=[];
  for(const variants of groups){
    if(selected.length>=count) break;
    selected.push(variants[Math.floor(Math.random()*variants.length)]);
  }
  return selected;
}
function selectQuestionSet(category){
  const pool=getQuestionPool(category);
  let history=loadQuestionHistory();
  let used=new Set(history[category]||[]);
  let available=pool.filter(q=>!used.has(questionKey(q)));

  // Jika soal yang belum pernah diselesaikan kurang dari 25, berarti satu
  // siklus sudah hampir habis. Mulai siklus baru agar tetap bisa bermain.
  if(available.length<QUESTION_COUNT_PER_ROUND){
    used=new Set();
    available=pool.slice();
  }

  activeQuestionSet=selectUniqueAnswerQuestions(available,QUESTION_COUNT_PER_ROUND,used);
  // Pengaman jika suatu saat bank diubah dan variasi unik kurang dari 25.
  if(activeQuestionSet.length<QUESTION_COUNT_PER_ROUND){
    activeQuestionSet=shuffleQuestions(available).slice(0,QUESTION_COUNT_PER_ROUND);
  }
  return activeQuestionSet;
}
function markQuestionSetCompleted(category){
  const history=loadQuestionHistory();
  const used=new Set(history[category]||[]);
  activeQuestionSet.forEach(q=>used.add(questionKey(q)));
  history[category]=[...used];
  saveQuestionHistory(history);
}
function getCurrentQuestions(category){
  return activeQuestionSet.length ? activeQuestionSet : selectQuestionSet(category);
}

let activeAlbum=null, activeSubalbum=null, activeStudent=null;
function renderStudents(){
  $("#studentGallery").innerHTML = students.map((s,i)=>`
    <article class="person">
      <img src="assets/${s.file}" alt="Foto ${s.name||"Murid PPLG 2"}" loading="lazy">
      <div class="person-info">
        <small>FOTO ${String(i+1).padStart(2,"0")}</small>
        <h3>${s.name||"Murid PPLG 2"}</h3>
        <button class="promo-link" data-student="${i}" type="button">📣 ${Array.isArray(promos[s.name]) && promos[s.name].length>1 ? `Promosi (${promos[s.name].length})` : "Promosi"}</button>
      </div>
    </article>`).join("");
  $$(".promo-link").forEach(b=>b.onclick=()=>showStudentPromo(+b.dataset.student));
}
function renderAlbums(){
  $("#albumGrid").innerHTML = albums.map(a=>`
    <article class="album album-clickable" data-album="${a.id}" tabindex="0" role="button">
      <img src="assets/${a.file}" alt="${a.title}" loading="lazy">
      <div class="album-caption"><h3>${a.title}</h3><p>${a.desc}</p><span class="album-open">Buka album →</span></div>
    </article>`).join("");
  $$(".album-clickable").forEach(el=>{
    const open=()=>showAlbum(el.dataset.album);
    el.onclick=open;
    el.onkeydown=e=>{if(e.key==="Enter"||e.key===" ") {e.preventDefault();open();}};
  });
}
function showAlbum(id){
  activeAlbum=albums.find(a=>a.id===id);
  if(!activeAlbum)return;
  activeSubalbum=null;
  $("#albumGrid").classList.add("hidden");
  $("#albumDetail").classList.remove("hidden");
  renderAlbumDetail();
}
function renderAlbumDetail(){
  const a=activeAlbum;
  if(!a)return;
  if(!activeSubalbum){
    $("#albumDetail").innerHTML=`
      <div class="detail-head"><button class="back-game" id="backToAlbums">← Kembali ke Album</button><div><span class="eyebrow">ALBUM</span><h3>${a.title}</h3><p>${a.desc}</p></div></div>
      <div class="subalbum-grid">${a.subalbums.map(s=>`
        <article class="subalbum" data-subalbum="${s.id}">
          <img src="assets/${s.cover}" alt="${s.title}" loading="lazy">
          <div><h4>${s.title}</h4><p>${s.desc}</p><span>Buka album →</span></div>
        </article>`).join("")}</div>`;
    $("#backToAlbums").onclick=()=>{ $("#albumDetail").classList.add("hidden"); $("#albumGrid").classList.remove("hidden"); };
    $$(".subalbum").forEach(el=>el.onclick=()=>{activeSubalbum=a.subalbums.find(s=>s.id===el.dataset.subalbum);renderAlbumDetail();});
  }else{
    $("#albumDetail").innerHTML=`
      <div class="detail-head"><button class="back-game" id="backToSubalbums">← Kembali ke ${a.title}</button><div><span class="eyebrow">SUBALBUM</span><h3>${activeSubalbum.title}</h3><p>${activeSubalbum.desc}</p></div></div>
      <div class="photo-grid">${activeSubalbum.photos.map((f,i)=>`<img src="assets/${f}" alt="${activeSubalbum.title} foto ${i+1}" loading="lazy">`).join("")}</div>`;
    $("#backToSubalbums").onclick=()=>{activeSubalbum=null;renderAlbumDetail();};
  }
}
function showStudentPromo(index){
  activeStudent=students[index];
  const studentName=activeStudent?.name || "Murid PPLG 2";
  const promoList=Array.isArray(promos[studentName]) ? promos[studentName] : (promos[studentName] ? [promos[studentName]] : []);
  const content = promoList.length ? `
    <div class="promo-stack">
      ${promoList.map((promo,i)=>`
        <article class="promo-detail-card">
          <img src="assets/${promo.file}" alt="${promo.title}" loading="lazy">
          <div class="promo-body">
            <span class="eyebrow">PROMOSI ${i+1}</span>
            <h3>${promo.title}</h3>
            <p>${promo.desc}</p>
            ${promo.phone ? `<a class="btn primary" target="_blank" rel="noopener" href="https://wa.me/${promo.phone.replace(/\D/g,"")}">💬 Chat WhatsApp ${promo.phone}</a>` : ""}
          </div>
        </article>`).join("")}
    </div>` : `
    <div class="promo-empty">
      <div class="promo-empty-icon">📣</div>
      <span class="eyebrow">PROMOSI ${studentName}</span>
      <h3>Belum ada promosi</h3>
      <p>Ruang promosi milik <b>${studentName}</b> masih kosong. Jika nanti ada usaha atau dagangan yang ingin dipromosikan, tambahkan datanya khusus untuk murid ini.</p>
    </div>`;

  const promoCount=promoList.length;
  const label=promoCount>1 ? `Ada ${promoCount} promosi` : (promoCount===1 ? "Ada 1 promosi" : "Belum ada promosi");
  $("#promoDetail").innerHTML=`
    <div class="detail-head">
      <button class="back-game" id="backToStudents">← Kembali ke Foto Murid</button>
      <div>
        <span class="eyebrow">PROMOSI MURID</span>
        <h3>${studentName}</h3>
        <p>${label}. Setiap promosi memiliki bagian sendiri.</p>
      </div>
    </div>
    ${content}`;

  location.hash="promo-detail";
  $("#backToStudents").onclick=()=>{location.hash="foto";};
}

const drawer=$("#drawer"), backdrop=$("#backdrop");
function openMenu(){drawer.classList.add("open");backdrop.classList.add("show");drawer.setAttribute("aria-hidden","false");$("#menuBtn").setAttribute("aria-expanded","true")}
function closeMenu(){drawer.classList.remove("open");backdrop.classList.remove("show");drawer.setAttribute("aria-hidden","true");$("#menuBtn").setAttribute("aria-expanded","false")}
$("#menuBtn").onclick=openMenu;$("#closeMenu").onclick=closeMenu;backdrop.onclick=closeMenu;

function route(){
  let id=location.hash.slice(1)||"home";
  if(!document.getElementById(id)) id="home";
  $$(".page").forEach(p=>p.classList.toggle("active",p.id===id));
  $$(".nav a").forEach(a=>a.classList.toggle("active",a.dataset.route===id));
  closeMenu(); window.scrollTo({top:0,behavior:document.body.classList.contains("reduce")?"auto":"smooth"});
}
window.addEventListener("hashchange",route);

function renderCategories(){
  const names={TKR:"TKR • Teknik Kendaraan Ringan",TKJ:"TKJ • Teknik Komputer & Jaringan",AKL:"AKL • Akuntansi & Keuangan Lembaga",KU:"KU • Kuliner / Tata Boga",RPL:"RPL • Rekayasa Perangkat Lunak",RANDOM:"RANDOM • Sejarah, IPA, IPS & Seni Budaya"};
  $("#categoryGrid").innerHTML=Object.entries(names).map(([key,label],i)=>`<button class="category" data-cat="${key}"><b>${String(i+1).padStart(2,"0")} / ${key}</b><small>${label.replace(key+" • ","")}</small><br><small>25 soal</small></button>`).join("");
}
function showPanel(id){
  ["gameChooser","ttsMenu","ttsGame","trophyGame"].forEach(x=>$("#"+x).classList.add("hidden"));
  $("#"+id).classList.remove("hidden");
}
$$(".game-card").forEach(b=>b.onclick=()=>showPanel(b.dataset.game==="tts"?"ttsMenu":"trophyGame"));
$$(".back-game").forEach(b=>b.onclick=()=>showPanel(b.dataset.back==="chooser"?"gameChooser":"ttsMenu"));

let currentCategory=null,currentPuzzle=null;
function cleanWord(s){return s.toUpperCase().replace(/[^A-Z]/g,"")}
function buildCrossword(category, newQuestionSet=false){
  if(newQuestionSet || currentCategory!==category || activeQuestionSet.length!==QUESTION_COUNT_PER_ROUND){
    selectQuestionSet(category);
  }
  currentCategory=category;
  const entries=getCurrentQuestions(category).map((x,i)=>({num:i+1,clue:x[0],word:cleanWord(x[1])})).sort((a,b)=>b.word.length-a.word.length);
  const N=31, center=Math.floor(N/2), grid=Array.from({length:N},()=>Array(N).fill(null)), placements=[];
  const put=(word,r,c,dir,num)=>{
    for(let i=0;i<word.length;i++){const rr=r+(dir==="D"?i:0),cc=c+(dir==="A"?i:0);grid[rr][cc]=word[i]}
    placements.push({num,word,r,c,dir});
  };
  put(entries[0].word,center,Math.floor((N-entries[0].word.length)/2),"A",entries[0].num);
  for(let ei=1;ei<entries.length;ei++){
    const e=entries[ei]; let best=null, tries=0;
    for(let r=1;r<N-1 && tries<700;r++) for(let c=1;c<N-1 && tries<700;c++){
      for(const dir of ["A","D"]){
        if(best) break;
        for(let i=0;i<e.word.length;i++){
          const rr=r+(dir==="D"?i:0),cc=c+(dir==="A"?i:0);
          if(rr<1||rr>=N-1||cc<1||cc>=N-1) continue;
          let ok=true, cross=false;
          for(let j=0;j<e.word.length;j++){
            const ar=r+(dir==="D"?j:0),ac=c+(dir==="A"?j:0), ch=grid[ar][ac];
            if(ch && ch!==e.word[j]){ok=false;break}
            if(ch===e.word[j])cross=true;
            const pr=ar+(dir==="D"?0:1), pc=ac+(dir==="A"?0:1);
            const pr2=ar-(dir==="D"?0:1),pc2=ac-(dir==="A"?0:1);
            // Side-neighbor rule prevents adjacent parallel words.
            if(dir==="A"){
              if((grid[ar-1]?.[ac] && grid[ar-1][ac]!==e.word[j]) || (grid[ar+1]?.[ac] && grid[ar+1][ac]!==e.word[j])){}
            }
          }
          if(ok && cross){best={r,c,dir};break}
        }
      }
      tries++;
    }
    if(!best){
      for(let r=1;r<N-1&&!best;r++) for(let c=1;c<N-1&&!best;c++) for(const dir of ["A","D"]){
        if(r+(dir==="D"?e.word.length-1:0)>=N-1||c+(dir==="A"?e.word.length-1:0)>=N-1) continue;
        let ok=true; for(let j=0;j<e.word.length;j++){const rr=r+(dir==="D"?j:0),cc=c+(dir==="A"?j:0);if(grid[rr][cc]){ok=false;break}}
        if(ok)best={r,c,dir};
      }
    }
    if(best)put(e.word,best.r,best.c,best.dir,e.num);
  }
  currentPuzzle={N,grid,placements,answers:entries.reduce((o,e)=>{o[e.num]=e.word;return o},{})};
  renderCrossword();
}
function renderCrossword(){
  const {N,grid,placements}=currentPuzzle, root=$("#crossword");
  const nums={}; placements.forEach(p=>nums[`${p.r},${p.c}`]=p.num);
  root.innerHTML="";
  for(let r=0;r<N;r++) for(let c=0;c<N;c++){
    const cell=document.createElement("div");cell.className="cell";
    if(grid[r][c]){
      const input=document.createElement("input");input.maxLength=1;input.dataset.r=r;input.dataset.c=c;input.autocomplete="off";
      input.addEventListener("input",()=>{input.value=cleanWord(input.value).slice(-1);});
      input.addEventListener("keydown",e=>{if(e.key==="ArrowRight")moveCell(r,c,0,1);if(e.key==="ArrowLeft")moveCell(r,c,0,-1);if(e.key==="ArrowDown")moveCell(r,c,1,0);if(e.key==="ArrowUp")moveCell(r,c,-1,0)});
      cell.appendChild(input);if(nums[`${r},${c}`]){const n=document.createElement("span");n.className="num";n.textContent=nums[`${r},${c}`];cell.appendChild(n)}
    } else cell.classList.add("block");
    root.appendChild(cell);
  }
  $("#clueList").innerHTML=placements.sort((a,b)=>a.num-b.num).map(p=>`<div class="clue" data-num="${p.num}"><b>${p.num}</b><span>${getCurrentQuestions(currentCategory)[p.num-1][0]}</span></div>`).join("");
  $$(".clue").forEach(c=>c.onclick=()=>focusPlacement(+c.dataset.num));
  $("#ttsCategoryLabel").textContent=currentCategory;
  $("#ttsTitle").textContent=({TKR:"Teknik Kendaraan Ringan",TKJ:"Teknik Komputer & Jaringan",AKL:"Akuntansi & Keuangan Lembaga",KU:"Kuliner / Tata Boga",RPL:"Rekayasa Perangkat Lunak",RANDOM:"Random"})[currentCategory]+` • Putaran ${currentRound}`;
  $("#ttsScore").textContent="0 / 25 benar";$("#ttsMessage").textContent="";
}
function moveCell(r,c,dr,dc){let rr=r+dr,cc=c+dc;while(rr>=0&&rr<31&&cc>=0&&cc<31&&!currentPuzzle.grid[rr][cc]){rr+=dr;cc+=dc}const el=document.querySelector(`input[data-r="${rr}"][data-c="${cc}"]`);if(el)el.focus()}
function focusPlacement(num){const p=currentPuzzle.placements.find(x=>x.num===num);if(!p)return;const el=document.querySelector(`input[data-r="${p.r}"][data-c="${p.c}"]`);if(el){el.focus();el.parentElement.scrollIntoView({block:"center",inline:"center"})};$$(".clue").forEach(c=>c.classList.toggle("active",+c.dataset.num===num))}
function checkTts(){
  let correct=0,total=0;
  $$("#crossword input").forEach(i=>{const p=currentPuzzle.placements.find(p=>{for(let k=0;k<p.word.length;k++){if(p.r+(p.dir==="D"?k:0)==i.dataset.r&&p.c+(p.dir==="A"?k:0)==i.dataset.c)return true}return false});});
  currentPuzzle.placements.forEach(p=>{
    let ok=true;
    for(let k=0;k<p.word.length;k++){const r=p.r+(p.dir==="D"?k:0),c=p.c+(p.dir==="A"?k:0),i=document.querySelector(`input[data-r="${r}"][data-c="${c}"]`);if(!i||i.value!==p.word[k])ok=false}
    if(ok)correct++;
  });
  $("#ttsScore").textContent=`${correct} / 25 benar`;
  if(correct===25){
    const finishedRound=currentRound;
    markQuestionSetCompleted(currentCategory);
    currentRound++;
    $("#ttsMessage").textContent=` 🎉 Putaran ${finishedRound} selesai! 25 soal baru sedang diacak...`;
    toast(`Mantap! 25 soal selesai. Memuat 25 soal baru yang diacak.`);
    setTimeout(()=>buildCrossword(currentCategory,true),450);
  }else{
    $("#ttsMessage").textContent=` • Masih ada ${25-correct} yang perlu diperiksa.`;
    toast("Jawaban sudah diperiksa.");
  }
}
$("#checkTts").onclick=checkTts;
$("#categoryGrid").addEventListener("click",e=>{const b=e.target.closest("[data-cat]");if(!b)return;currentRound=1;buildCrossword(b.dataset.cat,true);showPanel("ttsGame")});

let trophyRunning=false,trophyScore=0,timeLeft=60,timer=null;
function moveTrophy(){
  const field=$("#trophyField"), t=$("#trophy"), maxX=Math.max(0,field.clientWidth-70),maxY=Math.max(0,field.clientHeight-70);
  t.style.left=Math.floor(Math.random()*maxX)+"px";t.style.top=Math.floor(Math.random()*maxY)+"px";t.classList.add("visible");
}
function startTrophy(){
  clearInterval(timer);trophyRunning=true;trophyScore=0;timeLeft=60;$("#trophyScore").textContent=0;$("#timeLeft").textContent=60;$("#trophy").classList.add("visible");$(".trophy-intro")?.remove?.();moveTrophy();
  timer=setInterval(()=>{timeLeft--;$("#timeLeft").textContent=timeLeft;if(timeLeft<=0){clearInterval(timer);trophyRunning=false;$("#trophy").classList.remove("visible");toast(`Waktu habis! Skor kamu: ${trophyScore}`)}},1000);
}
$("#startTrophy").onclick=startTrophy;
$("#trophy").onclick=()=>{if(!trophyRunning)return;trophyScore++;$("#trophyScore").textContent=trophyScore;moveTrophy()};
window.addEventListener("resize",()=>{if(trophyRunning)moveTrophy()});

function loadSettings(){
  const s=JSON.parse(localStorage.getItem("pplg2-settings")||"{}");
  $("#darkMode").checked=!!s.dark;$("#reduceMotion").checked=!!s.reduce;$("#fontSize").value=s.size||"normal";
  document.body.classList.toggle("dark",!!s.dark);document.body.classList.toggle("reduce",!!s.reduce);document.body.classList.toggle("large",s.size==="large");document.body.classList.toggle("xl",s.size==="xl");
}
function saveSettings(){
  const s={dark:$("#darkMode").checked,reduce:$("#reduceMotion").checked,size:$("#fontSize").value};
  localStorage.setItem("pplg2-settings",JSON.stringify(s));loadSettings();
}
$("#darkMode").onchange=saveSettings;$("#reduceMotion").onchange=saveSettings;$("#fontSize").onchange=saveSettings;
$("#resetSettings").onclick=()=>{localStorage.removeItem("pplg2-settings");loadSettings();toast("Pengaturan dikembalikan.")};

renderStudents();renderAlbums();renderCategories();loadSettings();route();